<script setup lang="ts">
import {computed,onScopeDispose,ref,shallowRef,watch} from 'vue'
import {onBeforeRouteLeave,onBeforeRouteUpdate,useRouter} from 'vue-router'
import {can,currentProject,projectId,session} from '@/core/session'
import {ApiError,IdentityChanged,errorMessage,identityEpoch,onIdentityChange} from '@/core/http'
import AsyncState from '@/ui/AsyncState.vue'
import DeviceTypePanelCard from './DeviceTypePanelCard.vue'
import {typeDeviceUuid} from './type-devices-api'
import {decodePanelDraft,emptyPanelStyle,panelReceiptMatches,panelTransport,preparePanelSave,type PanelDraft,type PanelComponent,type PanelItem,type PanelResponse,type PanelIntent,type PanelTransport} from './device-type-panel-api'
const props=withDefaults(defineProps<{typeId:string;transport?:PanelTransport}>(),{transport:()=>panelTransport})
const router=useRouter(),roles=['OWNER','ADMIN','OPERATOR','VIEWER'],denied=ref(false)
const member=computed(()=>session.ready&&!session.transitioning&&!!session.user?.accountId&&can('device:read')&&typeDeviceUuid.test(projectId.value)&&typeDeviceUuid.test(props.typeId)&&roles.includes(session.user?.projectRole||'')&&roles.includes(currentProject.value?.myRole||'')),readable=computed(()=>member.value&&!denied.value)
const writable=computed(()=>readable.value&&can('device:update')&&currentProject.value?.status==='ACTIVE'&&['OWNER','ADMIN'].includes(session.user?.projectRole||'')&&['OWNER','ADMIN'].includes(currentProject.value?.myRole||''))
const snapshot=shallowRef<PanelResponse>(),draft=ref<PanelDraft>(),selected=ref(''),panelTab=ref('component'),busy=ref(false),error=ref(''),notice=ref(''),unknown=ref(false),conflict=ref(false),intent=shallowRef<PanelIntent>(),observed=shallowRef<PanelResponse>(),choosing=ref(false),selection=ref<string[]>([])
const active=computed(()=>draft.value?.components.find(c=>c.id===selected.value)),dirty=computed(()=>!!draft.value&&!!snapshot.value&&JSON.stringify(draft.value)!==JSON.stringify(snapshot.value.draft)),locked=computed(()=>busy.value||unknown.value||dirty.value||choosing.value),editable=computed(()=>writable.value&&!busy.value&&!unknown.value&&!conflict.value),itemsCount=computed(()=>draft.value?.components.reduce((count,c)=>count+c.items.length,0)||0)
const colorFields=[['valueColor','数值颜色'],['nameColor','属性名称颜色'],['iconForegroundColor','图标前景色'],['iconBackgroundColor','图标背景色']] as const
let alive=true,generation=0,controller:AbortController|undefined
function capture(){return{generation,epoch:identityEpoch(),project:projectId.value,actor:session.user?.accountId,typeId:props.typeId}}
function current(s:ReturnType<typeof capture>){return alive&&readable.value&&s.generation===generation&&s.epoch===identityEpoch()&&s.project===projectId.value&&s.actor===session.user?.accountId&&s.typeId===props.typeId}
function reset(){generation++;controller?.abort();snapshot.value=undefined;draft.value=undefined;selected.value='';busy.value=false;error.value='';notice.value='';unknown.value=false;conflict.value=false;intent.value=undefined;observed.value=undefined;choosing.value=false;selection.value=[];panelTab.value='component'}
function bind(value:PanelResponse){snapshot.value=value;draft.value=decodePanelDraft(value.draft);if(!draft.value.components.some(c=>c.id===selected.value))selected.value=draft.value.components[0]?.id||''}
function fail(cause:unknown){if(cause instanceof ApiError&&[401,403,404].includes(cause.status)){reset();denied.value=true}error.value=errorMessage(cause)}
async function load(){if(!readable.value||busy.value||unknown.value||dirty.value)return;const s=capture();busy.value=true;error.value='';controller=new AbortController();try{const value=await props.transport.read(s.project,s.typeId,controller.signal);if(current(s)){bind(value);conflict.value=false}}catch(cause){if(current(s)&&!(cause instanceof IdentityChanged))fail(cause)}finally{if(current(s))busy.value=false}}
function addCard(){if(!editable.value||!draft.value||draft.value.components.length>=32)return;const id=crypto.randomUUID();draft.value.components.push({id,kind:'ICON_NUMBER_CARD',items:[],style:emptyPanelStyle(),marginTop:0,marginBottom:0});selected.value=id;notice.value=''}
function removeCard(){if(!editable.value||!draft.value||!active.value)return;const id=active.value.id;draft.value.components=draft.value.components.filter(c=>c.id!==id);selected.value=draft.value.components[0]?.id||''}
function moveCard(delta:number){if(!editable.value||!draft.value||!active.value)return;const rows=draft.value.components,index=rows.findIndex(c=>c.id===selected.value),next=index+delta;if(next<0||next>=rows.length)return;[rows[index],rows[next]]=[rows[next]!,rows[index]!]}
function moveItem(index:number,delta:number){if(!editable.value||!active.value)return;const rows=active.value.items,next=index+delta;if(next<0||next>=rows.length)return;[rows[index],rows[next]]=[rows[next]!,rows[index]!]}
function removeItem(index:number){if(editable.value&&active.value)active.value.items.splice(index,1)}
function openChoices(){if(!editable.value||!active.value)return;selection.value=active.value.items.map(item=>item.propertyId);choosing.value=true}
function choose(){if(!editable.value||!snapshot.value||!active.value)return;const previous=active.value.items,chosen=new Set(selection.value),rows=previous.filter(item=>chosen.has(item.propertyId));for(const property of snapshot.value.currentNumberProperties)if(chosen.has(property.id)&&!rows.some(item=>item.propertyId===property.id))rows.push({propertyId:property.id,propertyKey:property.propertyKey,displayName:property.name,iconId:'mdi-thermometer',iconColor:null});if(rows.length>100||itemsCount.value-previous.length+rows.length>256){error.value='每卡最多100项，全部组件合计最多256项';return}active.value.items=rows;choosing.value=false}
function missing(item:PanelItem){return!snapshot.value?.currentNumberProperties.some(p=>p.id===item.propertyId&&p.propertyKey===item.propertyKey)}
function label(item:PanelItem){return snapshot.value?.currentNumberProperties.find(p=>p.id===item.propertyId&&p.propertyKey===item.propertyKey)?.name||item.propertyKey}
function setColor(target:PanelItem|PanelComponent['style'],key:string,value:unknown){if(!editable.value||typeof value!=='string')return;(target as Record<string,unknown>)[key]=value===''?null:value}
function setMargin(key:'marginTop'|'marginBottom',value:number|undefined|null){if(editable.value&&active.value&&value!=null)active.value[key]=value}
async function save(){if(!editable.value||!dirty.value||!snapshot.value||!draft.value||choosing.value)return;let original:PanelIntent;try{original=preparePanelSave(projectId.value,props.typeId,snapshot.value,draft.value)}catch(cause){error.value=errorMessage(cause);return}intent.value=original;unknown.value=true;busy.value=true;observed.value=undefined;error.value='';notice.value='';const s=capture();controller=new AbortController();let accepted=false
 try{const saved=await props.transport.save(original,controller.signal);accepted=true;if(!current(s))return;if(!panelReceiptMatches(saved,original))throw new Error('面板保存回执与原草稿不一致，请只读核对当前配置');const actual=await props.transport.read(s.project,s.typeId,controller.signal);if(!current(s))return;if(actual.revision!==saved.revision||actual.definitionToken!==saved.definitionToken||JSON.stringify(actual.draft)!==JSON.stringify(saved.draft))throw new Error('当前面板已变化，请只读核对');bind(actual);unknown.value=false;intent.value=undefined;notice.value='类型面板草稿已保存并重新读取；不表示 App 已运行或发布'}catch(cause){if(current(s)&&!(cause instanceof IdentityChanged)){fail(cause);if(!accepted&&cause instanceof ApiError&&!cause.outcomeUnknown&&[400,409,413,422,429].includes(cause.status)&&cause.code!==10014){unknown.value=false;conflict.value=true;error.value='保存被拒绝：'+errorMessage(cause)+'。请读取当前草稿后明确采用，原编辑内容仍保留。'}}}finally{if(current(s))busy.value=false}
}
async function review(){if(!readable.value||busy.value||!intent.value||!unknown.value&&!conflict.value)return;const s=capture();busy.value=true;error.value='';controller=new AbortController();try{const actual=await props.transport.read(intent.value.project,intent.value.typeId,controller.signal);if(current(s))observed.value=actual}catch(cause){if(current(s)&&!(cause instanceof IdentityChanged))fail(cause)}finally{if(current(s))busy.value=false}}
function adopt(){if(!observed.value||busy.value||!readable.value)return;const wasUnknown=unknown.value;bind(observed.value);unknown.value=false;conflict.value=false;intent.value=undefined;observed.value=undefined;error.value='';notice.value=wasUnknown?'已采用当前草稿；原保存历史结果仍未确认，没有重新提交':'已采用当前草稿，可基于新版本重新编辑'}
function discard(){if(busy.value||unknown.value||!snapshot.value)return;draft.value=decodePanelDraft(snapshot.value.draft);conflict.value=false;intent.value=undefined;observed.value=undefined;selected.value=draft.value.components[0]?.id||'';notice.value='已放弃本地修改'}
function back(){if(!locked.value)void router.push({name:'device-type-detail',params:{typeId:props.typeId},query:{tab:'apps'}})}
onBeforeRouteLeave(()=>!readable.value||!locked.value);onBeforeRouteUpdate(()=>!readable.value||!locked.value)
watch([()=>projectId.value,()=>props.typeId,()=>session.user?.accountId,member,()=>props.transport],()=>{reset();denied.value=false;if(member.value)void load()},{immediate:true,flush:'sync'})
const dispose=onIdentityChange(()=>{reset();denied.value=false});onScopeDispose(()=>{alive=false;reset();dispose()})
</script>
<template><section class="panel-editor">
 <header><el-button :disabled="locked" @click="back">返回设备类型</el-button><div><h1>设备面板编辑器</h1><p>当前设备类型 · {{typeId}}</p></div><el-button type="primary" :loading="busy" :disabled="!editable||!dirty||choosing" @click="save">保存</el-button></header>
 <p class="scope-note">本版本提供图标数值卡片的草稿编辑与预览；只支持本类型的 Number 属性及当前可见的样式设置。未选择预览设备，数值以“-”展示；保存草稿不代表 App 已发布或运行。</p>
 <el-alert v-if="notice" :title="notice" type="info" :closable="false"/><el-alert v-if="error" :title="error" type="error" :closable="false"/>
 <section v-if="unknown||conflict" class="panel-review"><p>{{unknown?'原保存结果未确认；保留原请求正文，只读取当前草稿，不会再次提交。':'版本或属性定义已变化，请只读核对当前草稿。'}}</p><el-button :loading="busy" @click="review">读取当前草稿</el-button><template v-if="observed"><p>当前草稿修订：{{observed.revision}} · {{observed.draft.components.length}} 个组件。当前值相同也不能证明原保存历史结果。</p><el-button :disabled="busy" @click="adopt">采用当前草稿</el-button></template></section>
 <AsyncState :forbidden="!readable" :loading="busy&&!snapshot" :error="!snapshot?error:undefined" @retry="load"><template v-if="draft&&snapshot">
  <p v-if="!writable" class="scope-note">当前角色或项目状态仅允许读取面板草稿。</p><div class="editor-grid">
   <aside class="library"><h2>基础组件</h2><h3>数值展示</h3><article class="library-card"><strong>图标数值卡片</strong><p>双列网格，图标、数值与名称并排展示。</p><el-button :disabled="!editable||draft.components.length>=32" @click="addCard">添加组件</el-button></article><p class="scope-note">{{draft.components.length}} / 32 个组件</p><el-button v-if="dirty&&!unknown" :disabled="busy" @click="discard">放弃本地修改</el-button></aside>
   <main class="phone-stage"><section class="phone-preview"><h2>设备列表</h2><div class="phone"><div class="phone-bar">ThingsX · 设备列表</div><h3>我的设备</h3><div class="device-list-empty">未选择预览设备</div></div></section><section class="phone-preview"><h2>设备面板</h2><div class="phone"><div class="phone-bar">ThingsX · 设备面板</div><h3>设备详情</h3><p class="preview-help">未选择预览设备 · 仅预览布局</p><p v-if="!draft.components.length" class="no-components">请在左侧添加组件</p><button v-for="component in draft.components" :key="component.id" class="select-card" :class="{selected:component.id===selected}" :aria-label="'选择组件 '+component.id" @click="selected=component.id"><DeviceTypePanelCard :component="component"/></button></div></section></main>
   <aside class="inspector"><template v-if="active"><div class="component-order"><el-button size="small" :disabled="!editable||draft.components[0]?.id===selected" @click="moveCard(-1)">组件上移</el-button><el-button size="small" :disabled="!editable||draft.components.at(-1)?.id===selected" @click="moveCard(1)">组件下移</el-button><el-button size="small" type="danger" :disabled="!editable" @click="removeCard">移除组件</el-button></div><el-tabs v-model="panelTab"><el-tab-pane label="组件设置" name="component"><el-button :disabled="!editable" @click="openChoices">{{active.items.length?'已选 '+active.items.length+' 个属性':'选择属性'}}</el-button><h3>设置属性</h3><el-collapse><el-collapse-item v-for="(item,index) in active.items" :key="item.propertyId" :name="item.propertyId" :title="label(item)"><el-alert v-if="missing(item)" title="原属性已移除、重建或不再为数值；请明确移除后选择，不能自动重绑。" type="warning" :closable="false"/><el-form label-position="top" :disabled="!editable"><el-form-item label="显示名称（固定名称）"><el-input v-model="item.displayName" :aria-label="'显示名称 '+item.propertyKey" maxlength="128"/></el-form-item><el-form-item label="图标"><el-select v-model="item.iconId" :aria-label="'图标 '+item.propertyKey"><el-option :value="'mdi-thermometer'" label="温度计"/></el-select><el-button size="small" @click="item.iconId=null">清空</el-button></el-form-item><el-form-item label="图标颜色"><el-input :model-value="item.iconColor||''" :aria-label="'图标颜色 '+item.propertyKey" placeholder="继承组件颜色" maxlength="7" @update:model-value="setColor(item,'iconColor',$event)"/></el-form-item><p class="model-facts">属性：{{item.propertyKey}}<template v-if="!missing(item)"> · 单位：{{snapshot.currentNumberProperties.find(p=>p.id===item.propertyId)?.unit||'未配置'}} · 小数位：{{snapshot.currentNumberProperties.find(p=>p.id===item.propertyId)?.decimalPlaces??'未配置'}}</template></p><el-button size="small" :disabled="index===0" @click="moveItem(index,-1)">属性上移</el-button><el-button size="small" :disabled="index===active.items.length-1" @click="moveItem(index,1)">属性下移</el-button><el-button size="small" type="danger" @click="removeItem(index)">移除属性</el-button></el-form></el-collapse-item></el-collapse><el-form label-position="top" :disabled="!editable"><el-form-item label="组件上边距"><el-input-number :model-value="active.marginTop" aria-label="组件上边距" :min="-16" :max="300" :step="1" :precision="0" @update:model-value="setMargin('marginTop',$event)"/></el-form-item><el-form-item label="组件下边距"><el-input-number :model-value="active.marginBottom" aria-label="组件下边距" :min="-16" :max="300" :step="1" :precision="0" @update:model-value="setMargin('marginBottom',$event)"/></el-form-item></el-form></el-tab-pane><el-tab-pane label="样式编辑" name="style"><el-form label-position="top" :disabled="!editable"><el-form-item label="显示背景卡片"><el-switch v-model="active.style.backgroundCard" aria-label="显示背景卡片"/></el-form-item><el-form-item v-for="[key,title] in colorFields" :key="key" :label="title"><el-input :model-value="active.style[key]||''" :aria-label="title" placeholder="继承主题颜色" maxlength="7" @update:model-value="setColor(active!.style,key,$event)"/></el-form-item></el-form><p class="scope-note">颜色使用 #RRGGBB，留空继承。属性图标颜色优先于组件图标前景色。</p></el-tab-pane></el-tabs></template><p v-else class="scope-note">选择组件后在此设置</p></aside>
  </div>
 </template></AsyncState>
 <el-dialog :model-value="choosing&&readable" title="选择属性" width="min(760px,94vw)" :close-on-click-modal="false" @close="choosing=false"><p>仅选择当前设备类型的 Number 属性。属性顺序可在组件设置中调整。</p><el-checkbox-group v-model="selection" :disabled="!editable"><label v-for="p in snapshot?.currentNumberProperties" :key="p.id" class="property-choice"><el-checkbox :value="p.id" :aria-label="'选择属性 '+p.propertyKey">{{p.name}}</el-checkbox><span>{{p.propertyKey}} · Number</span></label><el-empty v-if="!snapshot?.currentNumberProperties.length" description="当前类型没有 Number 属性" :image-size="48"/></el-checkbox-group><p v-if="active?.items.some(missing)" class="scope-note">已失效的原属性保留在组件内；请在组件设置中明确移除。</p><template #footer><el-button @click="choosing=false">取消</el-button><el-button type="primary" :disabled="!editable" @click="choose">提交</el-button></template></el-dialog>
</section></template>
<style scoped>.panel-editor>header{display:flex;align-items:center;justify-content:space-between;gap:16px;padding:12px 0}.panel-editor h1{font-size:20px;margin:0;text-align:center}.panel-editor header p{font-size:11px;color:var(--tl-muted);text-align:center;margin:6px 0 0}.scope-note,.preview-help,.model-facts{font-size:12px;line-height:20px;color:var(--tl-muted)}.scope-note{margin:12px 0}.editor-grid{display:grid;grid-template-columns:220px minmax(550px,1fr) 330px;border:1px solid var(--tl-border);min-height:720px;margin-top:18px}.library,.inspector{padding:16px;background:white;min-width:0}.library{border-right:1px solid var(--tl-border)}.inspector{border-left:1px solid var(--tl-border)}h2{font-size:14px;font-weight:500;margin:0 0 18px}h3{font-size:13px;font-weight:500}.library-card{padding:14px;border:1px solid var(--tl-border);border-radius:4px}.library-card p{font-size:12px;line-height:20px;color:var(--tl-muted)}.phone-stage{display:flex;justify-content:center;gap:26px;background:#f1f2f4;padding:28px 16px;overflow:auto}.phone-preview>h2{color:var(--tl-muted);margin:0 0 12px}.phone-preview{min-width:240px;width:260px}.phone{background:#f7f8fa;min-height:580px;overflow:hidden}.phone-bar{padding:10px;color:#888;background:white;font-size:11px}.phone h3{background:white;margin:0;padding:14px;text-align:center;font-size:15px;color:var(--tl-primary)}.device-list-empty,.no-components{margin:20px 12px;padding:24px 8px;border:1px dashed #ddd;font-size:12px;color:#999;text-align:center}.preview-help{text-align:center}.select-card{display:block;width:100%;border:1px solid transparent;padding:4px;background:transparent;text-align:initial;cursor:pointer;font:inherit}.select-card.selected{border:1px dashed var(--tl-primary)}.component-order{display:flex;flex-wrap:wrap;gap:6px;margin-bottom:14px}.component-order .el-button{margin-left:0}.inspector :deep(.el-form-item__content){gap:6px}.inspector :deep(.el-select){width:160px}.panel-review{padding:12px;border:1px solid var(--tl-border);margin:12px 0}.panel-review p{font-size:13px;line-height:21px}.property-choice{display:flex;align-items:center;justify-content:space-between;padding:8px;border-bottom:1px solid var(--tl-border)}.property-choice>span{font-size:12px;color:var(--tl-muted)}@media(max-width:1150px){.editor-grid{grid-template-columns:180px minmax(280px,1fr)}.inspector{grid-column:1/-1;border-top:1px solid var(--tl-border);border-left:0}.phone-stage{justify-content:flex-start}}@media(max-width:620px){.editor-grid{display:block}.library{border-right:0;border-bottom:1px solid var(--tl-border)}.phone-stage{gap:16px}.panel-editor>header{flex-wrap:wrap}.panel-editor h1{text-align:left;font-size:18px}.panel-editor header p{text-align:left;overflow-wrap:anywhere}}</style>
